def get_refills():
    prescriptions_response = list_prescriptions(name="Jordan Ellis", date_of_birth="1988-03-14")
    prescriptions = prescriptions_response.get("prescriptions", [])

    # Looking for cholesterol medication
    cholesterol_meds = ["atorvastatin", "simvastatin", "rosuvastatin", "pravastatin", "lovastatin", "fluvastatin", "pitavastatin"]

    for med in prescriptions:
        med_name = med['medication'].lower()
        if any(c_med in med_name for c_med in cholesterol_meds):
            refills_response = check_refills(prescription_id=med['prescription_id'])
            return {
                "medication": med['medication'],
                "refills": refills_response.get("refills_remaining")
            }
    return None

